const ctx = GameAPI.ctx;
const canvas = GameAPI.canvas;
const players = GameAPI.players;

// 每次按下按鍵，產生一個往上飄的標籤
const floatEvents = [];

GameAPI.onInput((playerId, key, state, p) => {
  if (state !== 'down') return;
  const pArr = [...players.values()];
  const i = pArr.indexOf(p);
  const cols = Math.ceil(Math.sqrt(pArr.length)) || 1;
  const cw = canvas.width / cols;
  const ch = canvas.height / Math.ceil(pArr.length / cols);
  const col = i % cols, row = Math.floor(i / cols);
  floatEvents.push({
    label: key,
    color: p.color,
    x: col * cw + cw / 2 + (Math.random() - 0.5) * cw * 0.25,
    y: row * ch + ch * 0.5,
    alpha: 1,
    scale: 0.4,
  });
});

GameAPI.update(() => {
  const W = canvas.width, H = canvas.height;

  // 背景半透明覆蓋，製造殘影效果
  ctx.fillStyle = 'rgba(0,0,16,0.25)';
  ctx.fillRect(0, 0, W, H);

  const pArr = [...players.values()];
  if (!pArr.length) return;
  const cols = Math.ceil(Math.sqrt(pArr.length));
  const rows = Math.ceil(pArr.length / cols);
  const cw = W / cols, ch = H / rows;

  // 畫每個玩家的區塊
  pArr.forEach((p, i) => {
    const col = i % cols, row = Math.floor(i / cols);
    const cx = col * cw + cw / 2, cy = row * ch + ch / 2;
    const active = p.inputs.size > 0;

    // 格子邊框（按下時發光）
    ctx.save();
    if (active) { ctx.shadowColor = p.color; ctx.shadowBlur = 24; }
    ctx.strokeStyle = active ? p.color : p.color + '33';
    ctx.lineWidth = active ? 2 : 1;
    ctx.strokeRect(col * cw + 8, row * ch + 8, cw - 16, ch - 16);
    ctx.restore();

    // 玩家名稱
    const fs = Math.min(cw * 0.1, 30);
    ctx.font = `700 ${fs}px monospace`;
    ctx.fillStyle = p.color;
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    ctx.fillText(p.name, cx, cy - ch * 0.2);

    // 目前按住的按鍵 → 顯示為方塊
    const keys = [...p.inputs];
    const bw = Math.min(cw / (keys.length + 1), 70);
    const startX = cx - (keys.length - 1) * (bw + 6) / 2;
    keys.forEach((key, ki) => {
      const bx = startX + ki * (bw + 6);
      const by = cy + ch * 0.05;
      ctx.save();
      ctx.shadowColor = p.color;
      ctx.shadowBlur = 16;
      ctx.fillStyle = p.color + 'bb';
      ctx.beginPath();
      ctx.roundRect(bx - bw / 2, by - bw * 0.35, bw, bw * 0.7, 8);
      ctx.fill();
      ctx.restore();
      ctx.fillStyle = '#fff';
      ctx.font = `700 ${bw * 0.38}px monospace`;
      ctx.fillText(key, bx, by);
    });
  });

  // 飄字動畫
  for (let i = floatEvents.length - 1; i >= 0; i--) {
    const e = floatEvents[i];
    e.alpha -= 0.02;
    e.scale  = Math.min(e.scale + 0.08, 1.3);
    e.y -= 2;
    if (e.alpha <= 0) { floatEvents.splice(i, 1); continue; }
    ctx.save();
    ctx.globalAlpha = e.alpha;
    ctx.translate(e.x, e.y);
    ctx.scale(e.scale, e.scale);
    ctx.shadowColor = e.color;
    ctx.shadowBlur = 24;
    ctx.fillStyle = e.color;
    ctx.font = '900 40px monospace';
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    ctx.fillText(e.label, 0, 0);
    ctx.restore();
  }
});
